INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Aries', '', 'Sự nghiệp và danh tiếng được thúc đẩy bởi tinh thần tiên phong, sự quyết đoán và mong muốn dẫn đầu trong lĩnh vực chuyên môn.', 'Bạn khao khát là người đầu tiên, người dẫn đường trong sự nghiệp. Bạn thích khởi nghiệp, lãnh đạo dự án mới và không chấp nhận vai trò phụ thuộc.', 'Năng lực lãnh đạo bẩm sinh, tinh thần doanh nhân và khả năng khởi tạo sự nghiệp từ con số không.', 'Xung đột với cấp trên, bốc đồng trong quyết định sự nghiệp và khó duy trì dự án khi hết giai đoạn khởi đầu hứng thú.', 'Bạn cần sự nghiệp cho phép sự độc lập. Đối tác phải hiểu rằng sự nghiệp là một phần quan trọng bản sắc của bạn.', 'Kiên nhẫn xây dựng sự nghiệp bền vững. Sự khởi đầu mạnh mẽ cần được bổ sung bằng sự bền bỉ lâu dài.', ARRAY['Nhà 10', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Taurus', '', 'Sự nghiệp và danh tiếng xây dựng trên sự ổn định, kiên nhẫn và giá trị thực tế bền vững. Thành công đến chậm nhưng chắc chắn.', 'Bạn xây dựng sự nghiệp từ từ, vững chắc và đáng tin cậy. Bạn bị thu hút bởi tài chính, bất động sản, nghệ thuật hoặc ẩm thực.', 'Sự bền bỉ phi thường trong sự nghiệp, khả năng xây dựng thương hiệu cá nhân bền vững và tính đáng tin cậy chuyên nghiệp.', 'Ngại thay đổi nghề nghiệp khi cần, quá chậm chạp trong nắm bắt cơ hội và bám víu vị trí không còn phù hợp.', 'Bạn cần sự nghiệp mang lại an toàn tài chính. Đối tác phải tôn trọng nhịp độ và phương pháp làm việc của bạn.', 'Đón nhận sự thay đổi trong sự nghiệp khi cần. Sự linh hoạt không phản bội tính kiên định — nó bổ sung.', ARRAY['Nhà 10', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Gemini', '', 'Sự nghiệp và danh tiếng gắn liền với giao tiếp, đa dạng và sự linh hoạt trí tuệ. Bạn có thể có nhiều sự nghiệp.', 'Bạn có thể theo đuổi nhiều sự nghiệp cùng lúc hoặc thay đổi nghề nghiệp nhiều lần. Bạn thành công trong truyền thông, viết lách, giảng dạy hoặc bán hàng.', 'Khả năng giao tiếp chuyên nghiệp xuất sắc, tính linh hoạt trong sự nghiệp và tài năng kết nối đa ngành.', 'Thiếu tập trung trong sự nghiệp, thay đổi hướng đi quá thường xuyên và hình ảnh công chúng không nhất quán.', 'Bạn cần sự nghiệp kích thích trí tuệ. Đối tác phải chấp nhận rằng bạn có thể thay đổi hướng sự nghiệp và điều đó là ổn.', 'Tìm một lĩnh vực đủ rộng để linh hoạt nhưng đủ sâu để xây dựng chuyên môn. Đa dạng trong một lĩnh vực mạnh.', ARRAY['Nhà 10', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Cancer', '', 'Sự nghiệp và danh tiếng gắn liền với việc chăm sóc, nuôi dưỡng và tạo dựng cảm giác an toàn cho cộng đồng.', 'Bạn thành công trong các lĩnh vực chăm sóc — y tế, giáo dục, ẩm thực, bất động sản. Danh tiếng gắn liền với sự ấm áp và đáng tin cậy.', 'Bản năng chăm sóc trong môi trường chuyên nghiệp, trực giác kinh doanh mạnh mẽ và khả năng tạo tổ chức ấm áp.', 'Cảm xúc chi phối quyết định sự nghiệp, khó tách rời đời sống cá nhân và công việc, dễ bị tổn thương bởi phê bình công khai.', 'Bạn xem đồng nghiệp như gia đình. Sự nghiệp phải cho phép bạn chăm sóc — cả con người lẫn kết quả công việc.', 'Phát triển sự chuyên nghiệp trong cách xử lý cảm xúc tại nơi làm việc. Sự mạnh mẽ bao gồm cả biết khi nào cần lý trí.', ARRAY['Nhà 10', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Leo', '', 'Sự nghiệp và danh tiếng là sân khấu lớn — sự tỏa sáng, lãnh đạo sáng tạo và mong muốn để lại dấu ấn không thể phai mờ.', 'Bạn khao khát sự nổi bật trong sự nghiệp — CEO, nghệ sĩ, nhà lãnh đạo. Bạn muốn được ghi nhớ và ngưỡng mộ cho thành tựu.', 'Sức hút lãnh đạo mạnh mẽ, sáng tạo trong kinh doanh và khả năng xây dựng thương hiệu cá nhân rực rỡ.', 'Cần sự ngưỡng mộ từ công chúng, cái tôi lớn trong môi trường chuyên nghiệp và khó chấp nhận vai trò hỗ trợ.', 'Sự nghiệp là nguồn tự hào lớn nhất. Đối tác cần hiểu và ủng hộ khát vọng tỏa sáng của bạn.', 'Lãnh đạo thực sự phục vụ người khác, không chỉ tỏa sáng. Xây dựng đội ngũ mạnh quan trọng hơn ngôi sao đơn lẻ.', ARRAY['Nhà 10', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Virgo', '', 'Sự nghiệp và danh tiếng dựa trên sự tỉ mỉ, phục vụ xuất sắc và khả năng cải thiện mọi hệ thống. Bạn là chuyên gia hoàn thiện.', 'Bạn thành công qua sự chuyên nghiệp, chú ý chi tiết và phục vụ tận tâm. Lĩnh vực phù hợp: y tế, kế toán, tư vấn, nghiên cứu.', 'Đạo đức làm việc phi thường, sự chính xác chuyên nghiệp và danh tiếng đáng tin cậy, hiệu quả.', 'Cầu toàn cản trở thăng tiến, tự hạ thấp giá trị bản thân và lo lắng thái quá về hình ảnh công chúng.', 'Bạn thể hiện năng lực qua kết quả thực tế. Đối tác phải hiểu rằng sự nghiệp là phương tiện phục vụ, không chỉ thu nhập.', 'Nhận ra giá trị của mình và đòi hỏi sự công nhận xứng đáng. Sự khiêm tốn quá mức là rào cản thành công.', ARRAY['Nhà 10', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Libra', '', 'Sự nghiệp và danh tiếng hướng tới sự hài hòa, ngoại giao và tạo dựng mối quan hệ chuyên nghiệp mạnh mẽ.', 'Bạn thành công trong lĩnh vực đòi hỏi ngoại giao — luật, quan hệ công chúng, nghệ thuật, thiết kế. Danh tiếng gắn liền với sự công bằng và duyên dáng.', 'Kỹ năng quan hệ chuyên nghiệp xuất sắc, hình ảnh công chúng thanh lịch và khả năng xây dựng liên minh chiến lược.', 'Do dự trong quyết định sự nghiệp quan trọng, phụ thuộc vào sự hợp tác và khó hoạt động độc lập.', 'Bạn cần sự nghiệp cho phép hợp tác. Đối tác kinh doanh hoặc bạn đời hỗ trợ rất quan trọng cho sự thăng tiến.', 'Đôi khi cần ra quyết định một mình. Sự nghiệp đòi hỏi cả sự ngoại giao lẫn sự quyết đoán.', ARRAY['Nhà 10', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Scorpio', '', 'Sự nghiệp và danh tiếng mang chiều sâu mãnh liệt — quyền lực, chuyển hóa và khả năng ảnh hưởng âm thầm nhưng sâu sắc.', 'Bạn bị thu hút bởi quyền lực trong sự nghiệp — tâm lý học, tài chính, điều tra, phẫu thuật. Bạn ảnh hưởng từ hậu trường nhiều hơn sân khấu.', 'Sức mạnh chiến lược phi thường, khả năng phát hiện cơ hội ẩn giấu và sức bật sự nghiệp sau mọi thất bại.', 'Tranh giành quyền lực tại nơi làm việc, xu hướng kiểm soát và danh tiếng bí ẩn có thể gây nghi ngờ.', 'Sự nghiệp là nguồn sức mạnh cá nhân. Đối tác phải tôn trọng sự tham vọng và chiều sâu chuyên nghiệp của bạn.', 'Sử dụng sức mạnh sự nghiệp để chuyển hóa tích cực. Quyền lực lớn nhất là biến bóng tối thành ánh sáng.', ARRAY['Nhà 10', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Sagittarius', '', 'Sự nghiệp và danh tiếng hướng tới sự mở rộng, tự do và truyền tải tri thức. Bạn sinh ra để truyền cảm hứng trên quy mô lớn.', 'Bạn thành công trong giáo dục, xuất bản, du lịch hoặc luật quốc tế. Sự nghiệp phải mang lại ý nghĩa và tự do — công việc tù túng giết chết bạn.', 'Tầm nhìn sự nghiệp rộng lớn, khả năng truyền cảm hứng cho đám đông và tinh thần lạc quan bất chấp thử thách.', 'Thiếu kỷ luật trong sự nghiệp, hứa quá nhiều làm ít và xu hướng bỏ bê chi tiết quan trọng.', 'Sự nghiệp gắn liền với tầm nhìn lớn. Đối tác phải chia sẻ hoặc ít nhất tôn trọng khát vọng mở rộng của bạn.', 'Chi tiết cũng quan trọng. Kết hợp tầm nhìn lớn với kế hoạch thực thi cụ thể để đạt thành công bền vững.', ARRAY['Nhà 10', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Capricorn', '', 'Sự nghiệp và danh tiếng ở đây mạnh mẽ nhất — kỷ luật sắt, tham vọng không giới hạn và mong muốn xây dựng di sản lâu bền.', 'Bạn sinh ra để thành công. Bạn có thể mất nhiều thời gian nhưng cuối cùng luôn đạt đỉnh cao. Sự nghiệp là trung tâm cuộc sống.', 'Kỷ luật sự nghiệp phi thường, tư duy chiến lược dài hạn và khả năng xây dựng đế chế từ con số không.', 'Workaholic cực đoan, hy sinh mọi thứ cho sự nghiệp và nỗi sợ thất bại có thể dẫn đến trầm cảm.', 'Sự nghiệp có thể gây áp lực lên mối quan hệ. Đối tác phải cực kỳ kiên nhẫn và hiểu rằng thành công cần thời gian.', 'Thành công không có ý nghĩa nếu không có ai để chia sẻ. Cân bằng tham vọng sự nghiệp với cuộc sống cá nhân.', ARRAY['Nhà 10', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Aquarius', '', 'Sự nghiệp và danh tiếng gắn liền với đổi mới, cách mạng và mong muốn thay đổi thế giới qua công việc.', 'Bạn thành công trong công nghệ, khoa học, cải cách xã hội hoặc lĩnh vực đi đầu xu thế. Sự nghiệp phi truyền thống là sở trường.', 'Tư duy đổi mới trong sự nghiệp, tầm nhìn tương lai và khả năng phá vỡ quy tắc cũ để tạo con đường mới.', 'Nổi loạn với hệ thống quản lý, khó chấp nhận vai trò truyền thống và sự nghiệp thất thường do quá khác biệt.', 'Sự nghiệp gắn liền với lý tưởng cá nhân. Đối tác phải tôn trọng tầm nhìn cách mạng của bạn.', 'Đổi mới cần cả nền tảng truyền thống. Kết hợp tư duy tương lai với kinh nghiệm quá khứ để thành công bền vững.', ARRAY['Nhà 10', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Pisces', '', 'Sự nghiệp và danh tiếng mang tính nghệ thuật, tâm linh hoặc phục vụ. Bạn tìm kiếm sự nghiệp có ý nghĩa sâu sắc hơn tiền bạc.', 'Bạn thành công trong nghệ thuật, chữa lành, tâm lý trị liệu hoặc từ thiện. Sự nghiệp cần phục vụ mục đích cao hơn bản thân.', 'Trực giác sự nghiệp mạnh mẽ, khả năng truyền cảm hứng qua nghệ thuật và lòng trắc ẩn trong phục vụ chuyên nghiệp.', 'Thiếu tham vọng thực tế, mơ hồ về mục tiêu sự nghiệp và dễ bị lợi dụng trong môi trường chuyên nghiệp.', 'Sự nghiệp gắn liền với sứ mệnh tâm linh. Đối tác phải hiểu rằng thành công đối với bạn không đo bằng tiền.', 'Kết hợp lý tưởng với thực tế. Bạn có thể phục vụ thế giới tốt hơn khi có nền tảng tài chính vững chắc.', ARRAY['Nhà 10', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Aries', '', 'Tình bạn, cộng đồng và ước mơ được thúc đẩy bởi tinh thần tiên phong, sự năng động và mong muốn dẫn đầu trong nhóm.', 'Bạn là người khởi xướng trong nhóm bạn, luôn đề xuất ý tưởng mới. Bạn thu hút bạn bè mạnh mẽ, độc lập và có tinh thần chiến đấu.', 'Khả năng lãnh đạo nhóm bạn, năng lượng truyền cảm hứng cho cộng đồng và tinh thần theo đuổi ước mơ mãnh liệt.', 'Xung đột trong nhóm bạn, khó hợp tác bình đẳng và xu hướng áp đặt ý tưởng lên cả nhóm.', 'Bạn bè phải mạnh mẽ và tự lập. Bạn không chịu được những người yếu đuối hoặc phụ thuộc.', 'Học cách lắng nghe và hợp tác trong nhóm. Ước mơ lớn cần sự đóng góp của nhiều người.', ARRAY['Nhà 11', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Taurus', '', 'Tình bạn bền vững, ổn định và dựa trên giá trị chung. Ước mơ gắn liền với an toàn vật chất và sự thoải mái.', 'Bạn có ít bạn thân nhưng rất trung thành. Bạn thích hoạt động nhóm thực tế — nấu ăn, làm vườn, chia sẻ sở thích thẩm mỹ.', 'Lòng trung thành phi thường trong tình bạn, khả năng xây dựng mạng lưới bền vững và giá trị chung vững chắc.', 'Bám víu bạn bè cũ dù đã xa cách, kháng cự mở rộng vòng tròn xã hội và ước mơ hạn chế trong vùng an toàn.', 'Bạn bè là gia đình thứ hai. Bạn thể hiện tình bạn qua sự hiện diện bền bỉ và những bữa ăn chung ấm áp.', 'Mở rộng tầm nhìn về ước mơ. Sự thoải mái vật chất là nền tảng nhưng không phải mục đích cuối cùng.', ARRAY['Nhà 11', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Gemini', '', 'Tình bạn, cộng đồng và ước mơ được nuôi dưỡng bởi sự giao tiếp, đa dạng trí tuệ và mạng lưới rộng lớn.', 'Bạn có mạng lưới quen biết khổng lồ nhưng ít bạn thân sâu sắc. Bạn là trung tâm thông tin, kết nối mọi người và chia sẻ ý tưởng.', 'Kỹ năng kết nối xã hội xuất sắc, khả năng tạo mạng lưới rộng và tài năng tổ chức sự kiện cộng đồng.', 'Tình bạn hời hợt, không bền sâu và khó cam kết với một nhóm hoặc mục tiêu cộng đồng lâu dài.', 'Bạn bè cần kích thích trí tuệ liên tục. Bạn thích đa dạng trong vòng tròn xã hội — mỗi bạn bè mang lại góc nhìn khác.', 'Xây dựng vài tình bạn thực sự sâu sắc bên cạnh mạng lưới rộng. Chiều sâu và chiều rộng đều cần thiết.', ARRAY['Nhà 11', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Cancer', '', 'Tình bạn gắn bó sâu sắc như gia đình. Ước mơ hướng tới tạo dựng cộng đồng an toàn, ấm áp cho mọi người.', 'Bạn xem bạn thân như anh chị em. Bạn là người chăm sóc trong nhóm bạn — nấu ăn cho mọi người, lắng nghe tâm sự, tạo không gian an toàn.', 'Tình bạn sâu sắc và bền chặt, khả năng tạo cảm giác thuộc về trong cộng đồng và trực giác về nhu cầu bạn bè.', 'Quá nhạy cảm với xung đột nhóm, sợ bị loại ra khỏi nhóm và bám víu tình bạn đã không còn phù hợp.', 'Bạn bè cần cảm thấy như gia đình. Bạn bảo vệ mãnh liệt nhưng đôi khi quá bảo bọc nhóm bạn thân.', 'Mở rộng vòng tròn xã hội. Bạn bè mới không đe dọa bạn bè cũ — trái tim đủ rộng cho tất cả.', ARRAY['Nhà 11', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Leo', '', 'Tình bạn rực rỡ, cộng đồng sáng tạo và ước mơ lớn lao, hoành tráng. Bạn tỏa sáng trong mọi nhóm.', 'Bạn là ngôi sao trong nhóm bạn — hào phóng, vui vẻ và luôn tổ chức tiệc tùng. Ước mơ gắn liền với sự sáng tạo và công nhận.', 'Sức hút xã hội mạnh mẽ, khả năng truyền cảm hứng cho nhóm và tính hào phóng trong tình bạn.', 'Cần là trung tâm chú ý trong nhóm, dễ tổn thương khi không được công nhận và xu hướng áp đảo bạn bè.', 'Bạn bè ngưỡng mộ sự hào phóng và năng lượng tích cực. Bạn cần bạn bè xứng đáng đứng cạnh trên "sân khấu."', 'Chia sẻ ánh đèn với bạn bè. Tình bạn thực sự dựa trên sự bình đẳng, không phải sự ngưỡng mộ.', ARRAY['Nhà 11', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Virgo', '', 'Tình bạn dựa trên sự phục vụ lẫn nhau, cải thiện và giá trị thực tế. Ước mơ hướng tới cải thiện xã hội.', 'Bạn giúp đỡ bạn bè bằng hành động cụ thể — giải quyết vấn đề, tư vấn, hỗ trợ thực tế. Bạn tham gia cộng đồng có mục đích rõ ràng.', 'Tình bạn thực tế và đáng tin cậy, khả năng cải thiện nhóm và đóng góp cụ thể cho cộng đồng.', 'Phê phán bạn bè, kỳ vọng quá cao từ nhóm và khó chấp nhận khi người khác không đáp ứng tiêu chuẩn.', 'Bạn bè biết có thể dựa vào bạn. Bạn thể hiện tình bạn qua sự giúp đỡ thực tế hơn là lời nói.', 'Chấp nhận bạn bè với những khuyết điểm. Tình bạn không phải dự án cải thiện — nó cần sự chấp nhận.', ARRAY['Nhà 11', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Libra', '', 'Tình bạn thanh lịch, cộng đồng hài hòa và ước mơ về một thế giới công bằng, đẹp đẽ cho tất cả.', 'Bạn là nhà hòa giải trong nhóm bạn, luôn giữ hòa khí. Bạn bị thu hút bởi cộng đồng nghệ thuật, xã hội và các tổ chức công bằng.', 'Kỹ năng xã hội xuất sắc, khả năng hòa giải xung đột nhóm và tạo dựng cộng đồng thẩm mỹ, hài hòa.', 'Thỏa hiệp bản thân vì nhóm, do dự khi cần lên tiếng và phụ thuộc vào sự chấp thuận của bạn bè.', 'Bạn bè ngưỡng mộ sự thanh lịch và công bằng. Bạn tạo không gian an toàn cho mọi người bày tỏ.', 'Đôi khi cần bảo vệ lập trường trước nhóm bạn. Sự công bằng thực sự đòi hỏi can đảm phát biểu.', ARRAY['Nhà 11', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Scorpio', '', 'Tình bạn mãnh liệt, sâu sắc và dựa trên lòng trung thành tuyệt đối. Ước mơ gắn liền với sự chuyển hóa xã hội.', 'Bạn có ít bạn nhưng gắn bó sâu sắc như máu thịt. Bạn bị thu hút bởi cộng đồng bí mật, nhóm chuyển hóa hoặc phong trào cách mạng.', 'Lòng trung thành tuyệt đối trong tình bạn, khả năng tạo liên minh mạnh mẽ và sức ảnh hưởng sâu trong cộng đồng.', 'Ghen tuông trong tình bạn, xu hướng kiểm soát nhóm và khó tha thứ khi bạn bè phản bội.', 'Bạn bè phải chứng minh lòng trung thành. Bạn bảo vệ bạn bè mãnh liệt nhưng cũng đòi hỏi tương xứng.', 'Tin tưởng rộng rãi hơn. Không phải ai cũng là kẻ thù tiềm ẩn — cho phép mình dễ bị tổn thương với bạn bè.', ARRAY['Nhà 11', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Sagittarius', '', 'Tình bạn phiêu lưu, cộng đồng đa văn hóa và ước mơ lớn lao về tự do, tri thức và ý nghĩa.', 'Bạn có bạn bè từ khắp nơi trên thế giới. Bạn thích nhóm hoạt động phiêu lưu, triết học và mở rộng tầm nhìn.', 'Tầm nhìn rộng mở trong tình bạn, khả năng kết nối đa văn hóa và tinh thần lạc quan truyền nhiễm.', 'Hời hợt trong tình bạn gần, quá lý tưởng về cộng đồng và khó cam kết với một nhóm cố định.', 'Bạn bè là đồng hành phiêu lưu. Bạn cần nhóm bạn cởi mở, yêu tự do và thích khám phá.', 'Nuôi dưỡng tình bạn gần bên cạnh mạng lưới toàn cầu. Những người ở gần cũng cần sự quan tâm.', ARRAY['Nhà 11', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Capricorn', '', 'Tình bạn có cấu trúc, nghiêm túc và dựa trên sự tôn trọng lẫn nhau. Ước mơ gắn liền với thành tựu và địa vị.', 'Bạn chọn bạn bè cẩn thận — ưu tiên người có tham vọng, năng lực. Bạn tham gia cộng đồng mang tính chuyên nghiệp hoặc có mục tiêu rõ ràng.', 'Tình bạn bền vững và đáng tin cậy, mạng lưới chuyên nghiệp mạnh mẽ và khả năng lãnh đạo cộng đồng.', 'Tính toán trong tình bạn, khó thư giãn với bạn bè và xu hướng đánh giá bạn bè qua thành tựu.', 'Bạn bè kính trọng sự nghiêm túc và đáng tin cậy của bạn. Bạn là cố vấn và điểm tựa trong nhóm.', 'Cho phép tình bạn đơn giản vui vẻ. Không phải mối quan hệ nào cũng cần có mục đích hay kết quả.', ARRAY['Nhà 11', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Aquarius', '', 'Tình bạn và cộng đồng ở đây mạnh mẽ nhất — phi truyền thống, bình đẳng và hướng tới tương lai tốt đẹp hơn. Đây là vị trí tự nhiên.', 'Bạn là nhà hoạt động xã hội bẩm sinh. Bạn bè đa dạng, khác biệt và chia sẻ lý tưởng nhân văn. Bạn tham gia cộng đồng tiến bộ, đổi mới.', 'Tầm nhìn nhân văn phi thường, khả năng kết nối cộng đồng đa dạng và tư duy đổi mới trong hoạt động nhóm.', 'Xa cách cảm xúc trong tình bạn, quá lý tưởng về cộng đồng và khó chấp nhận khi người khác không chia sẻ lý tưởng.', 'Bạn bè là gia đình tự chọn. Bạn đối xử bình đẳng nhưng có thể giữ khoảng cách cảm xúc.', 'Kết nối cảm xúc với bạn bè bên cạnh kết nối trí tuệ. Tình bạn cần cả tâm hồn lẫn tư duy.', ARRAY['Nhà 11', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Pisces', '', 'Tình bạn mang tính tâm linh, ước mơ siêu việt và cộng đồng hướng tới sự chữa lành, cảm thương vạn vật.', 'Bạn kết nối với bạn bè ở cấp độ tâm hồn. Bạn bị thu hút bởi cộng đồng nghệ thuật, tâm linh hoặc từ thiện. Ước mơ vượt ra ngoài cá nhân.', 'Lòng trắc ẩn vô biên trong tình bạn, khả năng chữa lành nhóm và trực giác mạnh mẽ về nhu cầu cộng đồng.', 'Thiếu ranh giới trong tình bạn, dễ bị lợi dụng và mất bản thân trong lý tưởng cộng đồng.', 'Bạn bè cảm nhận sự ấm áp và lòng trắc ẩn từ bạn. Bạn là "linh hồn" của nhóm — người chữa lành và kết nối.', 'Thiết lập ranh giới trong tình bạn. Bạn có thể yêu thương cộng đồng mà vẫn bảo vệ sức khỏe cảm xúc riêng.', ARRAY['Nhà 11', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Aries', '', 'Tiềm thức chứa đựng năng lượng chiến đấu bị kìm nén, sự giận dữ ẩn giấu và nguồn sức mạnh nội tâm chưa được khai phá.', 'Bạn có thể kìm nén sự tức giận và tính quyết đoán. Đằng sau vẻ ngoài bình tĩnh, bạn mang trong mình một chiến binh đang chờ được giải phóng.', 'Nguồn năng lượng nội tâm tiềm ẩn khổng lồ, khả năng hành động quyết đoán khi thực sự cần và sức mạnh tâm linh chiến đấu.', 'Sự giận dữ bị kìm nén có thể bùng nổ bất ngờ, tự phá hoại và khó nhận ra sức mạnh bản thân.', 'Bạn có thể vô tình thu hút đối tác mạnh mẽ vì bạn chưa khai phá sức mạnh riêng. Nhận ra và sống trọn phẩm chất này.', 'Đối mặt với sự giận dữ ẩn giấu thay vì kìm nén. Năng lượng chiến binh được chấp nhận sẽ trở thành sức mạnh chữa lành.', ARRAY['Nhà 12', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Taurus', '', 'Tiềm thức chứa đựng mong muốn an toàn sâu sắc, giá trị ẩn giấu và mối quan hệ bí mật với thế giới vật chất.', 'Bạn có thể bí mật tích trữ tài sản hoặc che giấu nhu cầu thoải mái vật chất. Thiên nhiên và giác quan là con đường chữa lành tâm linh.', 'Trực giác tài chính ẩn giấu, khả năng tìm thấy sự bình yên qua thiên nhiên và chiều sâu giá trị nội tâm.', 'Bám víu vật chất một cách vô thức, sợ mất mát ẩn sâu và xu hướng tìm kiếm an toàn qua tích lũy bí mật.', 'Bạn cần học cách chia sẻ nhu cầu vật chất cởi mở. Sự dễ bị tổn thương về giá trị bản thân cần được chữa lành.', 'Buông bỏ sự bám víu vô thức vào vật chất. An toàn thực sự đến từ nội tâm, không phải từ tích lũy.', ARRAY['Nhà 12', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Gemini', '', 'Tiềm thức chứa đựng những suy nghĩ bất tận, đối thoại nội tâm và nỗi sợ không thể diễn đạt suy nghĩ thực sự.', 'Bạn có một thế giới nội tâm đầy ắp suy nghĩ mà bạn không chia sẻ. Viết lách bí mật, nhật ký hoặc thiền định có thể là phương pháp chữa lành.', 'Trí tuệ trực giác ẩn giấu, khả năng viết lách sâu sắc khi một mình và sự kết nối tiềm thức với tri thức phổ quát.', 'Lo âu tinh thần dai dẳng, khó ngủ vì suy nghĩ quá nhiều và cảm giác bị hiểu lầm.', 'Bạn có thể giữ nhiều bí mật trong mối quan hệ. Học cách chia sẻ những suy nghĩ sâu nhất với người tin tưởng.', 'Tìm sự yên tĩnh trong tâm trí. Thiền định và viết nhật ký giúp chuyển hóa suy nghĩ hỗn loạn thành trí tuệ.', ARRAY['Nhà 12', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Cancer', '', 'Tiềm thức chứa đựng nỗi đau gia đình sâu thẳm, ký ức tuổi thơ ẩn giấu và nhu cầu chữa lành cảm xúc nguồn cội.', 'Bạn mang trong mình những cảm xúc gia đình chưa được giải quyết. Giấc mơ có thể đầy ký ức tuổi thơ. Bạn cần thời gian một mình để chữa lành.', 'Trực giác cảm xúc phi thường, khả năng chữa lành người khác qua sự đồng cảm và chiều sâu tâm hồn vô tận.', 'Nỗi đau gia đình chưa giải quyết chi phối vô thức, xu hướng chìm đắm trong cảm xúc và khó buông bỏ quá khứ.', 'Bạn có thể vô tình mang vết thương gia đình vào mối quan hệ. Nhận thức và chữa lành là chìa khóa.', 'Đối mặt với nỗi đau tuổi thơ thay vì chôn vùi. Mỗi giọt nước mắt được khóc ra là một bước gần hơn tới tự do.', ARRAY['Nhà 12', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Leo', '', 'Tiềm thức chứa đựng nhu cầu được công nhận bị kìm nén, sáng tạo ẩn giấu và sức mạnh nội tâm rực rỡ chưa được bộc lộ.', 'Bạn có thể ẩn giấu tài năng sáng tạo hoặc kìm nén nhu cầu tỏa sáng. Đằng sau sự khiêm tốn là một ngôi sao chờ được phát hiện.', 'Sức sáng tạo nội tâm phi thường, khả năng biểu diễn trong khi ẩn danh và sức mạnh tâm linh sáng chói.', 'Kìm nén nhu cầu được chú ý, cảm giác tội lỗi khi muốn tỏa sáng và khó nhận ra giá trị sáng tạo bản thân.', 'Bạn có thể thu hút đối tác thu hút ánh đèn sân khấu thay cho bạn. Nhận ra và sống trọn sức mạnh sáng tạo riêng.', 'Cho phép ánh sáng nội tâm tỏa ra. Kìm nén sáng tạo là từ chối bản chất thực sự — hãy tỏa sáng.', ARRAY['Nhà 12', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Virgo', '', 'Tiềm thức chứa đựng sự lo lắng ẩn giấu, tự phê bình nội tâm và mong muốn phục vụ ở cấp độ tâm linh.', 'Bạn có thể lo lắng vô thức về sức khỏe, công việc hoặc sự hoàn hảo. Phục vụ thầm lặng và thiền định giúp bạn tìm bình yên nội tâm.', 'Khả năng phục vụ tâm linh sâu sắc, trực giác chẩn đoán và sự chữa lành qua hành động phục vụ.', 'Lo âu dai dẳng ẩn dưới bề mặt, tự phê bình nội tâm khắc nghiệt và xu hướng cầu toàn vô thức.', 'Bạn có thể bí mật lo lắng cho đối phương mà không nói ra. Chia sẻ nỗi lo giúp giải phóng gánh nặng tinh thần.', 'Buông bỏ nhu cầu kiểm soát mọi thứ. Sự không hoàn hảo là một phần thiêng liêng của cuộc sống.', ARRAY['Nhà 12', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Libra', '', 'Tiềm thức chứa đựng nhu cầu kết nối sâu thẳm, nỗi sợ cô đơn ẩn giấu và mong muốn hài hòa hoàn toàn.', 'Bạn có thể bí mật sợ cô đơn hoặc ẩn giấu mối quan hệ. Tâm linh đến qua nghệ thuật, thiền định và kết nối sâu sắc.', 'Sự nhạy cảm thẩm mỹ tâm linh, khả năng tạo hài hòa vô hình và trực giác về cân bằng vũ trụ.', 'Phụ thuộc vô thức vào người khác, sợ đối mặt bóng tối nội tâm một mình và hy sinh bản thân bí mật cho hòa bình.', 'Bạn có thể mang gánh nặng tình cảm mà đối phương không nhận ra. Chia sẻ nhu cầu ẩn giấu cần sự can đảm.', 'Học cách ở một mình và tìm sự hài hòa nội tâm. Cân bằng thực sự bắt đầu từ bên trong.', ARRAY['Nhà 12', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Scorpio', '', 'Tiềm thức chứa đựng sức mạnh chuyển hóa khổng lồ, bí mật sâu thẳm và mối liên hệ mãnh liệt với bóng tối và ánh sáng.', 'Bạn mang trong mình những bí mật sâu thẳm và sức mạnh tâm lý phi thường. Giấc mơ có thể rất mãnh liệt, thậm chí tiên tri.', 'Sức mạnh chuyển hóa tâm linh phi thường, trực giác thấu thị và khả năng phục hồi từ bất kỳ bóng tối nào.', 'Ám ảnh bí mật, sợ bộc lộ sự dễ bị tổn thương sâu nhất và xu hướng tự hủy hoại vô thức.', 'Bạn mang chiều sâu tâm lý phi thường vào mối quan hệ. Chữa lành vết thương ẩn giấu giải phóng tiềm năng tình yêu.', 'Đối mặt với bóng tối nội tâm thay vì kìm nén. Phượng hoàng chỉ bay lên từ đống tro tàn khi chấp nhận ngọn lửa.', ARRAY['Nhà 12', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Sagittarius', '', 'Tiềm thức chứa đựng khát vọng tự do vô tận, niềm tin ẩn giấu và mong muốn siêu thoát khỏi mọi giới hạn.', 'Bạn có thể bí mật mơ về cuộc sống tự do hoàn toàn. Tâm linh gắn liền với triết học, thiền định và hành trình nội tâm vĩ đại.', 'Trực giác triết học sâu sắc, khả năng tìm ý nghĩa trong sự cô đơn và tầm nhìn tâm linh rộng mở.', 'Trốn tránh thực tại qua mộng mơ phiêu lưu, niềm tin vô thức không thực tế và khó bén rễ tại hiện thực.', 'Bạn cần chia sẻ giấc mơ sâu nhất với đối phương. Ẩn giấu khát vọng tự do tạo khoảng cách vô hình.', 'Tự do thực sự là sự giải thoát nội tâm. Du hành bên trong cũng vĩ đại như du hành thế giới bên ngoài.', ARRAY['Nhà 12', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Capricorn', '', 'Tiềm thức chứa đựng áp lực trách nhiệm ẩn giấu, nỗi sợ thất bại sâu thẳm và mong muốn kiểm soát vô thức.', 'Bạn mang gánh nặng trách nhiệm vô hình. Bạn có thể làm việc bí mật, cô đơn gánh vác hoặc cảm thấy tội lỗi khi nghỉ ngơi.', 'Sức chịu đựng nội tâm phi thường, khả năng hoàn thành nhiệm vụ không ai biết và tính kỷ luật tâm linh.', 'Trầm cảm ẩn giấu, cảm giác tội lỗi vô lý và kìm nén nhu cầu nghỉ ngơi cho đến khi kiệt sức.', 'Bạn gánh vác nhiều hơn đối phương thấy. Chia sẻ gánh nặng là biểu hiện của sức mạnh, không phải yếu đuối.', 'Cho phép bản thân yếu đuối. Nghỉ ngơi không phải lười biếng — nó là sự tái sinh cần thiết.', ARRAY['Nhà 12', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Aquarius', '', 'Tiềm thức chứa đựng lý tưởng nhân văn sâu sắc, cảm giác cô lập ẩn giấu và mong muốn kết nối với tập thể ở cấp vô thức.', 'Bạn có thể cảm thấy khác biệt vô thức, như thể không hoàn toàn thuộc về bất kỳ nhóm nào. Tâm linh gắn liền với ý thức tập thể.', 'Trực giác về xu hướng xã hội, khả năng nhìn thấy tương lai qua giấc mơ và sự kết nối tâm linh với nhân loại.', 'Cảm giác cô lập dù ở giữa đám đông, xa cách cảm xúc vô thức và khó chấp nhận sự bình thường.', 'Bạn mang chiều sâu trí tuệ tâm linh vào mối quan hệ. Chia sẻ cảm giác "khác biệt" giúp kết nối sâu hơn.', 'Chấp nhận sự thuộc về. Bạn không cần phải khác biệt để có giá trị — sự kết nối con người là đủ.', ARRAY['Nhà 12', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Pisces', '', 'Tiềm thức ở đây mạnh mẽ nhất — ranh giới hòa tan hoàn toàn, kết nối tâm linh sâu thẳm và sự giải thoát qua lòng trắc ẩn vô biên.', 'Bạn có mối liên kết tâm linh sâu sắc nhất. Giấc mơ mang thông điệp quan trọng. Bạn cần thời gian một mình để nạp năng lượng từ vũ trụ.', 'Sức mạnh tâm linh phi thường, khả năng chữa lành ở cấp vô thức và trực giác kết nối với nguồn năng lượng phổ quát.', 'Ranh giới cá nhân quá yếu, dễ bị ảnh hưởng bởi mọi năng lượng xung quanh và xu hướng trốn tránh thực tại qua ảo tưởng.', 'Bạn mang chiều sâu tâm linh vô tận vào mối quan hệ. Đối tác phải thấu hiểu nhu cầu cô đơn và tĩnh lặng của bạn.', 'Bám trụ vào thực tại trong khi bay trong cõi tâm linh. Thân thể và tâm hồn cần được chăm sóc song song.', ARRAY['Nhà 12', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, relationships = EXCLUDED.relationships, growth_path = EXCLUDED.growth_path, key_themes = EXCLUDED.key_themes;
